import{j as e}from"./index-5R4dUj_Z.js";import{P as i}from"./PageHero-BWjRxU5P.js";import"./vendor-Bu7HoccY.js";const s=["This privacy policy will help you understand how your personal information is collected, used and protected by Jaffari Sky Travels. By personal information we mean any information you provide to us - including your name, age, address, contact number, email address, card / payment information and, where relevant, the date of birth of children travelling with you, or any other such detail you choose to share.","We assure you that we follow appropriate security standards to protect your privacy when you use our website and book with us.","Jaffari Sky Travels does not sell or rent the personal information of our clients and users to any third party without the consent of the customer or user involved.","We use your information only with your consent, to deliver the products and services you have requested from us.","Financial information such as credit card, net-banking and debit card details is collected directly by the secure payment gateways and not stored by Jaffari Sky Travels.","We may share necessary information with our trusted service partners and agents to respond to your queries and resolve issues, with restrictions placed on how they may use that data.","Your basic information - such as name, age, phone number and address - is shared with the relevant service providers (such as airlines or hotel / accommodation providers) only as required to confirm your bookings.","We may disclose information when required by Indian or foreign government agencies for security, immigration or customs purposes, or as otherwise required by law.","Jaffari Sky Travels applies standard regulations and the best administrative and technical security measures available to us to protect your personal data from unauthorised access, alteration or disclosure.","Our website uses cookies to enhance your experience and to present customised information. Third parties such as Google may use cookies to serve advertisements based on your browsing history. You can control or disable cookies at any time through your browser settings, though some features of the site may then not function as intended.","Our website may contain links that connect you to entirely different websites. Jaffari Sky Travels bears no responsibility for the content or practices of those external sites, and we advise you to review their own terms and conditions and privacy policies before sharing any information with them.","If you have any questions about this privacy policy or how your information is handled, please reach out to us at jaffariskytravels@gmail.com"],c=["By confirming a booking with Jaffari Sky Travels, you acknowledge that you have read, understood and agreed to these terms and conditions. For any clarification, please contact us at jaffariskytravels@gmail.com","Jaffari Sky Travels requires only 20% of the total tour cost to confirm and secure your booking. This percentage may vary depending on the itinerary, trip category and duration.","The advance amount will be adjusted as per the recommendation of your personal travel consultant.","Online payments are accepted through our secure payment gateway.","A 3% additional charge will be levied on credit-card payments over the total amount.","All bank charges and payment-gateway fees on remittances must be borne by the passenger.","Any cancellation must be notified to Jaffari Sky Travels in writing.","Cancellation charges will be effective from the date on which we receive your cancellation in writing.","Cancellation of transportation tickets follows the rules of the respective authority.","Air tickets issued at special / promotional fares are non-refundable, and the applicable cancellation charges are borne by the guest.","Bookings made during peak tourist season may attract no refund on cancellation, regardless of the reason.","Peak-season policies vary by region and by hotel. Hotels may apply their own cancellation policies, which we are obliged to follow. Any excess charges arising from such cancellations are the responsibility of the client and not of the travel agent.","Itineraries are planned in advance, but mountain travel in Kashmir can be affected by weather, road conditions, landslides or other circumstances beyond our control. In such cases Jaffari Sky Travels reserves the right to amend, reschedule or substitute parts of the itinerary in the interest of your safety and comfort. We will always do our best to offer a suitable alternative of equal value.","Our website may contain links that connect you to entirely different websites. Jaffari Sky Travels bears no responsibility for the content or practices of those external sites, and we advise you to review their own terms and conditions and privacy policies before sharing any information with them."];function h({title:a}){const o=a==="Privacy Policy",t=o?s:c;return e.jsxs("main",{children:[e.jsx(i,{eyebrow:"Policy information",image:"/images/legal-page.jpg",text:o?"How we collect, use and protect your personal data.":"Terms and conditions for booking with us.",title:a}),e.jsx("section",{className:"section-wrap",children:e.jsxs("article",{className:"rounded-2xl bg-white p-7 shadow-travel max-w-4xl mx-auto",children:[e.jsx("h2",{className:"font-serif text-4xl text-kashmir-blue mb-8",children:a}),e.jsx("div",{className:"space-y-4",children:t.map((r,n)=>e.jsx("p",{className:"font-medium leading-relaxed text-kashmir-slate",children:r},n))})]})})]})}export{h as LegalPage};
